python3 - <<'PY'
import re, pathlib
ref = pathlib.Path('.patch-port/reference.diff').read_text()
gen = pathlib.Path('.patch-port/results/generated.patch').read_text()

def hunks(text, transform=None):
    out=[]
    cur=None
    for line in text.splitlines():
        if line.startswith('diff --git'):
            if transform: line=line.replace('a/fs/smb/server/','a/fs/ksmbd/').replace('b/fs/smb/server/','b/fs/ksmbd/')
            cur=None
        elif line.startswith('@@'):
            cur=line.split('@@')[2] if line.count('@@')>=2 else line
            out.append(['@@'])
        elif line.startswith(('--- ','+++ ','index ')):
            if transform:
                line=line.replace('a/fs/smb/server/','a/fs/ksmbd/').replace('b/fs/smb/server/','b/fs/ksmbd/')
        elif line.startswith(('+','-',' ')):
            if out: out[-1].append(line)
        elif line=='':
            pass
    return out

r=hunks(ref, transform=True)
g=hunks(gen)
print("ref hunk count:",len(r),"gen hunk count:",len(g))
ok=True
