        print(f"HUNK {i} differs")
        import difflib
        for l in difflib.unified_diff(a,b,lineterm=''):
            print(l)
print("HUNK_BODIES_IDENTICAL" if ok and len(r)==len(g) else "HUNKS_DIFFER")
# which files in each
print("ref files:", sorted(set(re.findall(r'diff --git a/(\S+)', ref))))
print("gen files:", sorted(set(re.findall(r'diff --git a/(\S+)', gen))))
PY
