    96	 * @wk:	smb work containing request command buffer
    97	 *
    98	 * called by kworker threads to processing remaining smb work requests
    99	 */
   100	static void handle_ksmbd_work(struct work_struct *wk)
   101	{
   102		struct ksmbd_work *work = container_of(wk, struct ksmbd_work, work);
   103		struct ksmbd_conn *conn = work->conn;
   104	
   105		atomic64_inc(&conn->stats.request_served);
   106	
   107		__handle_ksmbd_work(work, conn);
   108	
   109		ksmbd_conn_try_dequeue_request(work);
   110		ksmbd_free_work_struct(work);
   111		/*
   112		 * Checking waitqueue to dropping pending requests on
   113		 * disconnection. waitqueue_active is safe because it
   114		 * uses atomic operation for condition.
   115		 */
   116		if (!atomic_dec_return(&conn->r_count) && waitqueue_active(&conn->r_count_q))
   117			wake_up(&conn->r_count_q);
   118	}
