   121	 * queue_ksmbd_work() - queue a smb request to worker thread queue
   122	 *		for proccessing smb command and sending response
   123	 * @conn:	connection instance
   124	 *
   125	 * read remaining data from socket create and submit work.
   126	 */
   127	static int queue_ksmbd_work(struct ksmbd_conn *conn)
   128	{
   129		struct ksmbd_work *work;
   130	
   131		work = ksmbd_alloc_work_struct();
   132		if (!work) {
   133			pr_err("allocation for work failed\n");
   134			return -ENOMEM;
   135		}
   136	
   137		work->conn = conn;
   138		work->request_buf = conn->request_buf;
   139		conn->request_buf = NULL;
   140	
   141		ksmbd_init_smb_server(work);
   142	
   143		ksmbd_conn_enqueue_request(work);
   144		atomic_inc(&conn->r_count);
   145		/* update activity on connection */
   146		conn->last_active = jiffies;
   147		INIT_WORK(&work->work, handle_ksmbd_work);
   148		ksmbd_queue_work(work);
   149		return 0;
   150	}
